<?php

namespace App\Services\L2j;

/**
 * Item names/types/grades, class names, the XP table and boss names from the L2J Mobius Essence datapack
 * (resources/data/gamedata.json, generated by resources/data/build-gamedata.mjs).
 */
class GameData
{
    /** @var array{items: array<string, list<string>>, classes: array<string, string>, exp: array<string, int>, bosses: array<string, array{0: string, 1: int}>}|null */
    private ?array $data = null;

    /**
     * @return array{items: array<string, list<string>>, classes: array<string, string>, exp: array<string, int>, bosses: array<string, array{0: string, 1: int}>}
     */
    private function data(): array
    {
        return $this->data ??= json_decode((string) file_get_contents(config('l2j.gamedata')), true, flags: JSON_THROW_ON_ERROR);
    }

    /**
     * @return array{name: string, type: string, grade: string|null}
     */
    public function item(int $itemId): array
    {
        $item = $this->data()['items'][(string) $itemId] ?? null;

        return [
            'name' => $item[0] ?? "Unknown item {$itemId}",
            'type' => $item[1] ?? 'EtcItem',
            'grade' => $item[2] ?? null,
        ];
    }

    public function itemExists(int $itemId): bool
    {
        return isset($this->data()['items'][(string) $itemId]);
    }

    /**
     * Items whose name contains the search text, for admin pickers.
     *
     * @return array<int, string> item id => "Name (type, grade)"
     */
    public function searchItems(string $search, int $limit = 50): array
    {
        $search = mb_strtolower(trim($search));
        $results = [];

        foreach ($this->data()['items'] as $id => $item) {
            if ($search !== '' && ! str_contains(mb_strtolower($item[0]), $search) && (string) $id !== $search) {
                continue;
            }

            $results[(int) $id] = $this->itemLabel((int) $id);

            if (count($results) >= $limit) {
                break;
            }
        }

        return $results;
    }

    public function itemLabel(int $itemId): string
    {
        $item = $this->item($itemId);
        $details = array_filter([$item['type'], $item['grade'] ? "{$item['grade']}-grade" : null]);

        return "{$item['name']} (#{$itemId}, ".implode(', ', $details).')';
    }

    public function className(int $classId): string
    {
        return $this->data()['classes'][(string) $classId] ?? "Class {$classId}";
    }

    /**
     * Total XP needed to reach a level, or null past the cap.
     */
    public function expForLevel(int $level): ?int
    {
        $exp = $this->data()['exp'][(string) $level] ?? null;

        return $exp === null ? null : (int) $exp;
    }

    /**
     * A raid or grand boss of the datapack (npc_respawns also holds other saved NPCs).
     */
    public function isRaidBoss(int $npcId): bool
    {
        return isset($this->data()['bosses'][(string) $npcId]);
    }

    /**
     * @return array{name: string, level: int|null}
     */
    public function boss(int $npcId): array
    {
        $boss = $this->data()['bosses'][(string) $npcId] ?? null;

        return ['name' => $boss[0] ?? "Boss {$npcId}", 'level' => $boss[1] ?? null];
    }
}
